/** 🏛️ One neutral vocabulary owner is independent of the OS binding and preserves literal wire data. */
import {dirname,join,resolve} from "node:path";
import Ajv from "ajv";
import * as toml from "@iarna/toml";
import {Database} from "bun:sqlite";
import {expect,test} from "bun:test";
import Parser from "web-tree-sitter";
import {parseArtifactRef} from "../../🟦️.ts";
import vocabulary from "../../🔣️.json";
import schema from "../🧬️schema/🔣️.json";
import corpus from "../🧫️fixtures/🔣️.json";
const owner=resolve(import.meta.dir,"../..");
const pkg=join(owner,"📦️packages/🦀️rust");
const sorted=(value:object)=>Object.fromEntries(Object.entries(value).sort(([a],[b])=>a.localeCompare(b)));

test("neutral vocabulary corpus matches closed schema and independent literal SQLite rows",()=>{
  const ajv=new Ajv({strict:false});ajv.addSchema(vocabulary);const admit=ajv.compile(schema);expect(admit(corpus)).toBe(true);
  for(const invalid of [{...corpus,unknown:true},{...corpus,normalDependencies:[...corpus.normalDependencies,"semio-framework-os-kernel"]}])expect(admit(invalid)).toBe(false);
  const db=new Database(":memory:");db.run("CREATE TABLE identity(artifact_id TEXT,kind TEXT,standard TEXT,subset TEXT)");
  try{for(const value of corpus.references){const actual=parseArtifactRef(value);db.run("DELETE FROM identity");db.run("INSERT INTO identity VALUES(?,?,?,?)",[actual.artifactId,actual.dialect.artifactKind,actual.dialect.standard,actual.dialect.subset]);expect(db.query("SELECT artifact_id AS artifactId,kind AS artifactKind,standard,subset FROM identity").get()).toEqual({artifactId:value.artifactId,...value.dialect});}}finally{db.close();}
  console.error("[DEBUG] Three literal vocabulary identities retained under independent schema and SQLite");
});

test("actual package has only owned general dependencies and an explicit complete export surface",async()=>{
  const text=await Bun.file(join(pkg,"Cargo.toml")).text();
  const first=Bun.TOML.parse(text) as {package:{name:string};dependencies:Record<string,{path:string}>};
  const oracle=toml.parse(text) as unknown as typeof first;
  expect(sorted(first.dependencies)).toEqual(sorted(oracle.dependencies));expect(first.package.name).toBe(corpus.packageName);
  expect(Object.keys(first.dependencies).sort()).toEqual([...corpus.normalDependencies].sort());
  for(const dependency of Object.values(first.dependencies)){const path=resolve(pkg,dependency.path,"Cargo.toml");expect(await Bun.file(path).exists()).toBe(true);expect(path.includes("/🛍️products/")).toBe(false);}
  const entry=await Bun.file(join(pkg,"🦀️.rs")).text();await Parser.init();const parser=new Parser();parser.setLanguage(await Parser.Language.load(join(dirname(Bun.resolveSync("tree-sitter-wasms/package.json",process.cwd())),"out","tree-sitter-rust.wasm")));
  expect(parser.parse(entry).rootNode.hasError()).toBe(false);expect(entry.includes("::*")).toBe(false);
  const exports=entry.slice(entry.indexOf("pub use vocabulary::{")+"pub use vocabulary::{".length,entry.lastIndexOf("};")).split(",").map(value=>value.trim()).filter(Boolean);
  expect(exports.sort()).toEqual([...corpus.exports].sort());console.error("[DEBUG] Nineteen explicit vocabulary exports and four general dependency owners");
});

test("neutral vocabulary implementation compiles without an OS field-binding namespace",async()=>{
  const source=await Bun.file(join(owner,"🦀️.rs")).text();
  expect(source.includes("mod reference;")).toBe(false);expect(source.includes("dsl::")).toBe(false);
  expect(source.includes("use semio_framework_value::serde::{Deserialize, Serialize};")).toBe(true);
});

#!/usr/bin/env bun
import {resolve} from "node:path";
import {BundleScript,ScriptRouter} from "../../../../🏃️process/🧭️routing/🟦️.ts";
import {runScriptMain} from "../../../../🏃️process/🧭️routing/🚪️entrypoint/🟦️.ts";
import {runBudgetedTestCommand} from "../../../../🏃️process/🧪️testing/🎛️execution/🟦️.ts";
import {runCargoTestsV1,readCargoTestPolicyV1} from "../../../../🏃️process/🧪️testing/🦀️cargo/🟦️.ts";
import {resolveTestLevel,testLevelBudgetMs} from "../../../../🏃️process/🧪️testing/🎚️budget/🟦️.ts";
import {cmdBudgetMs} from "../../../../🏃️process/⏱️budget/🟦️.ts";

/** 🏛️ Checks the actual independent vocabulary owner and literal wire fields. */
class OwnershipScript extends BundleScript {
  async run(segments:string[]):Promise<void>{
    if(segments.length)throw Error("test-ownership accepts no arguments");
    const source=resolve(this.root,"../../🏛️ownership/🧪️tests/🟦️.ts");
    await runBudgetedTestCommand(process.execPath,[Bun.resolveSync("typescript/bin/tsc",this.root),"--noEmit","--strict","--skipLibCheck","--allowImportingTsExtensions","--resolveJsonModule","--target","ESNext","--module","ESNext","--moduleResolution","bundler","--types","bun",source],{cwd:this.repoRoot,budgetMs:cmdBudgetMs(),throwOnFailure:true});
    await runBudgetedTestCommand(process.execPath,["test",source],{cwd:this.repoRoot,budgetMs:testLevelBudgetMs(),throwOnFailure:true});
  }
}

/** 🚪️ Runs every native vocabulary law without selecting a test name. */
class NativeScript extends BundleScript {
  async run(segments:string[]):Promise<void>{
    const{rest}=resolveTestLevel(segments);
    if(rest.length)throw Error("test-native accepts only an execution level");
    await runCargoTestsV1({manifestPath:resolve(this.root,"Cargo.toml"),packages:["semio-framework-io-schema"],cwd:this.root,extraArgs:["--lib","--no-fail-fast"]},readCargoTestPolicyV1(process.env));
  }
}
const router=new ScriptRouter(import.meta.dir).register("test-ownership",OwnershipScript).register("test-native",NativeScript);
await runScriptMain(router,{defaultCommand:"test-ownership"});
